CREATE TABLE IF NOT EXISTS emitters(id TEXT PRIMARY KEY, identity TEXT NOT NULL UNIQUE, name TEXT NOT NULL, data TEXT NOT NULL, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipients(id TEXT PRIMARY KEY, identity TEXT NOT NULL, name TEXT NOT NULL, data TEXT NOT NULL, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, identity TEXT NOT NULL UNIQUE, name TEXT NOT NULL, data TEXT NOT NULL, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sequences(id TEXT PRIMARY KEY, emitter_id TEXT NOT NULL REFERENCES emitters(id), serie INTEGER NOT NULL CHECK(serie BETWEEN 0 AND 999), next_number INTEGER NOT NULL CHECK(next_number BETWEEN 1 AND 1000000000), next_code INTEGER NOT NULL CHECK(next_code BETWEEN 1 AND 100000000), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(emitter_id,serie));
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY, emitter_id TEXT NOT NULL REFERENCES emitters(id), recipient_id TEXT NOT NULL REFERENCES recipients(id), serie INTEGER NOT NULL, number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 999999999), access_key TEXT NOT NULL UNIQUE CHECK(length(access_key)=44), numeric_code TEXT NOT NULL, check_digit TEXT NOT NULL, issue_date TEXT NOT NULL, total TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('GENERATED','ERROR','CANCELLED_TEST')), source_invoice_id TEXT REFERENCES invoices(id), snapshot TEXT NOT NULL, directory TEXT NOT NULL, xml_hash TEXT NOT NULL, pdf_hash TEXT NOT NULL, schema_profile TEXT NOT NULL, validation TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(emitter_id,serie,number));
CREATE TABLE IF NOT EXISTS invoice_items(id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), product_id TEXT NOT NULL REFERENCES products(id), item_number INTEGER NOT NULL, snapshot TEXT NOT NULL, UNIQUE(invoice_id,item_number));
CREATE TABLE IF NOT EXISTS generation_attempts(id TEXT PRIMARY KEY, request_id TEXT NOT NULL, stage TEXT NOT NULL, message TEXT NOT NULL, draft TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS invoices_created ON invoices(created_at DESC);
CREATE INDEX IF NOT EXISTS invoices_source ON invoices(source_invoice_id);
PRAGMA user_version = 1;
